head.script:
// https://inswave01.atlassian.net/browse/WAEA-1155



// 테스트 설명, 유효성 값 설정
//  ★ _5 : dummy_data * Column 속성 관련 옵션 중 병합 Column 옵션(ignoreSpan) 담당
//   - 같은 그룹의 type / checkButton 은 _2, aposPrefixOnNum / removeQuotation / removeNewLine / trim 은 _3,
//     spanAll 은 _4 담당이므로 제외
//   - 기본 옵션(fileName / delim / header), Column 선택 순서 옵션, 기타 옵션은 다른 샘플 담당이므로 제외
//   - description 은 saveCSV 분리 샘플 공통
scwin.tData = {
    "description" : "[gridView > M > saveCSV]<br/>GridView 컴포넌트의 데이터를 CSV 형식의 파일로 다운로드합니다.",
    "validation" : [
        "ignoreSpan(선택) 파라미터로 병합된 Column 의 데이터 처리 방식을 설정합니다.",
        "ignoreSpan(선택) 파라미터를 '0' 으로 설정 시 병합된 Column 을 하나의 Column 으로 처리하여 다운로드합니다.",
        "ignoreSpan(선택) 파라미터를 '1' 로 설정 시 병합된 Column 을 해제하여 별도의 Column 으로 각각 처리하여 다운로드합니다.",
        "ignoreSpan(선택) 파라미터를 생략하면 기본값 '0' 으로 동작합니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 : 병합(colSpan) Body Column 을 가진 GridView 를 동적 생성한다.
//  · Header 는 4 Column, Body 는 col1 / col2 / col3(colSpan=2) 로 col3 가 병합 Column 이다.
//  · ignoreSpan 값에 따라 CSV 의 Column 수와 값 배치가 달라져야 한다.
scwin.comp_init = async function () {
    // 기존 target / DataList 정리
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제]\n- Header 는 name1 / name2 / name3-a / name3-b 4 Column\n- Body 는 col1 / col2 / col3 3 Column 이며 col3 가 colSpan=2 로 병합된 Column\n[절차]\n1. par 옵션(options.ignoreSpan) 값을 선택한다 (빈값을 고르면 파라미터를 생략한다)\n2. saveCSV 버튼을 클릭하여 CSV 파일을 다운로드한다\n3. 다운로드한 파일을 메모장 등 텍스트 편집기로 열어 내용을 확인한다\n4. 옵션값(빈값 / 0 / 1) 별로 1~3 을 반복하여 파일 내용을 비교한다\n[확인] 다운로드한 파일에서 아래를 확인한다\n- 병합 Column(col3) 의 값이 몇 개의 Column 으로 기록되는지\n- 기본 구분 문자는 세미콜론이므로 세미콜론으로 나뉜 Column 수를 센다"', '', 'label1');

    // DataList 생성 (col1~col3 / 4행)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDl = '';
    strDl += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDl += '<w2:columnInfo>';
    strDl += '<w2:column id="col1" name="name1" dataType="text"></w2:column>';
    strDl += '<w2:column id="col2" name="name2" dataType="text"></w2:column>';
    strDl += '<w2:column id="col3" name="name3" dataType="text"></w2:column>';
    strDl += '</w2:columnInfo>';
    strDl += '<w2:data use="true">';
    strDl += '<w2:row><col1>a1</col1><col2>b1</col2><col3>merge1</col3></w2:row>';
    strDl += '<w2:row><col1>a2</col1><col2>b2</col2><col3>merge2</col3></w2:row>';
    strDl += '<w2:row><col1>a3</col1><col2>b3</col2><col3>merge3</col3></w2:row>';
    strDl += '<w2:row><col1>a4</col1><col2>b4</col2><col3>merge4</col3></w2:row>';
    strDl += '</w2:data>';
    strDl += '</w2:dataList>';
    $p.data.create(strDl);

    // target 생성 (DataList 바인딩 / Body col3 는 colSpan=2 병합 Column)
    let grp_comp = $c.gcm.getTestGroup();
    let cList = $c.gcm.createCList({ dataList : "data:dlt_bind" });

    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:600px;height:220px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="hcol1" value="name1"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="hcol2" value="name2"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="hcol3" value="name3-a"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="hcol4" value="name3-b"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="280" style="" colSpan="2" inputType="text" id="col3" dataList="col3"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// par 옵션값으로 saveCSV options 객체를 구성한다.
//  · 선택(필수여부 N) 파라미터는 미설정(빈값) 이면 객체에 담지 않아 생략되도록 한다.
//  · 미설정이면 빈 객체({}) 가 전달되어 ignoreSpan 이 기본값으로 동작한다.
scwin.buildOptions = function () {
    let options = {};

    let v = par_ignoreSpan.getValue();
    if (v !== "") options.ignoreSpan = v;

    return options;
}



// saveCSV 실행 : 검증은 다운로드된 CSV 파일의 실제 내용으로 한다.
//  · 어떤 옵션값으로 받은 파일인지 구분할 수 있도록 실제 전달한 options 만 한 줄로 출력한다.
scwin.btn_saveCSV_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let options = scwin.buildOptions();
    bottom.setReturnValue("saveCSV 호출 options : " + JSON.stringify(options));

    target1.saveCSV(options);
}
